begin;
create temp table arch_ids(promoteur uuid,pharmacie uuid,other_pharmacie uuid,target_resp uuid);
do $$ declare p uuid:=gen_random_uuid(); ph uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); target uuid:=gen_random_uuid(); conv uuid; begin alter table auth.users disable trigger on_auth_user_created; insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(p,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','arch-p@example.test','x',now(),'{}','{}',now(),now()),(target,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','arch-r@example.test','x',now(),'{}','{}',now(),now()); alter table auth.users enable trigger on_auth_user_created; insert into public.profiles(id,role,username,first_name,last_name,actif,niveau_interne,fonction_interne) values(p,'promoteur','archp','Arch','Promoteur',true,1,'promoteur'),(target,'pharmacie','archr','Arch','Responsable',true,0,'responsable'); insert into public.pharmacies(id,nom,ville,lat,lng,actif) values(ph,'Architecture A3','Yaoundé',3.87,11.52,true),(other,'Hors scope','Yaoundé',3.87,11.52,true); insert into public.promoteur_pharmacies(promoteur_id,pharmacie_id,actif) values(p,ph,true); insert into public.conventions_promoteurs(promoteur_id,montant_mensuel,date_expiration,statut,architecture_code) values(p,30000,current_date+30,'active','PARENTS_AINES_CADETS') returning id into conv; insert into public.abonnements_promoteurs(promoteur_id,convention_id,montant_mensuel,debut,echeance,statut) values(p,conv,30000,current_date,current_date+30,'actif'); insert into arch_ids values(p,ph,other,target); end $$; set local role authenticated; select public.naxa_has_privilege('CREATE_RESPONSABLE',(select pharmacie from arch_ids),'PHARMACIE') pass; select not public.naxa_has_privilege('CREATE_RESPONSABLE',(select other_pharmacie from arch_ids),'PHARMACIE') pass; do $$declare v uuid;begin v:=public.accrediter_profile((select target_resp from arch_ids),(select pharmacie from arch_ids),2,(select promoteur from arch_ids));if v is null then raise exception 'accreditation failed';end if;end$$; select (select p.fonction_interne='responsable' and p.niveau_interne=2 and p.pharmacie_id=(select pharmacie from arch_ids) and p.parent_profile_id=(select promoteur from arch_ids) from public.profiles p where p.id=(select target_resp from arch_ids)) pass; update public.conventions_promoteurs set date_expiration=current_date-1,statut='expiree' where promoteur_id=(select promoteur from arch_ids); update public.abonnements_promoteurs set echeance=current_date-1,statut='impaye' where promoteur_id=(select promoteur from arch_ids); select not public.naxa_can('CREATE_RESPONSABLE',(select pharmacie from arch_ids),'PHARMACIE') pass; update public.conventions_promoteurs set date_expiration=current_date+30,statut='active',architecture_code='ORPHELIN' where promoteur_id=(select promoteur from arch_ids); update public.abonnements_promoteurs set echeance=current_date+30,statut='actif' where promoteur_id=(select promoteur from arch_ids); select not public.naxa_has_privilege('CREATE_RESPONSABLE',(select pharmacie from arch_ids),'PHARMACIE') pass; rollback; select 'Architecture behavior suite' suite,true pass;